describe('Itemised Receipt After Checkout', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display itemised receipt with correct details after successful checkout', () => {
    // Intercept the checkout API call
    cy.intercept('POST', '/api/checkout/complete').as('checkoutComplete');

    // Add items to cart
    cy.get('[data-testid="add-to-cart-button"]').first().click();
    cy.get('[data-testid="product-1"]').first().click();
    cy.get('[data-testid="add-to-cart-button"]').first().click();
    cy.get('[data-testid="product-2"]').first().click();

    // Verify items are added
    cy.get('[data-testid="cart-item-count"]').should('contain', '2');

    // Proceed to checkout
    cy.get('[data-testid="checkout-button"]').click();

    // Verify checkout form is visible
    cy.get('[data-testid="checkout-form"]').should('be.visible');

    // Fill in shipping details
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="shipping-city-input"]').type('Anytown');
    cy.get('[data-testid="shipping-state-input"]').type('CA');
    cy.get('[data-testid="shipping-zip-code-input"]').type('90210');

    // Verify shipping details are filled
    cy.get('[data-testid="shipping-address-input"]').should('have.value', '123 Main St');

    // Verify billing details are pre-filled
    cy.get('[data-testid="billing-address-input"]').should('have.value', '123 Main St');

    // Verify payment method selection
    cy.get('[data-testid="payment-method-select"]').click();
    cy.get('[data-testid="credit-card-input"]').click();

    // Verify payment details are visible
    cy.get('[data-testid="payment-details-section"]').should('be.visible');

    // Fill in payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Verify payment details are filled
    cy.get('[data-testid="card-number-input"]').should('have.value', '4111111111111111');

    // Verify checkout button is enabled
    cy.get('[data-testid="checkout-button"]').should('be.enabled');

    // Click checkout button
    cy.get('[data-testid="checkout-button"]').click();

    // Wait for API call to complete
    cy.wait('@checkoutComplete');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Checkout successful');

    // Verify receipt is displayed
    cy.get('[data-testid="receipt-section"]').should('be.visible');
    cy.get('[data-testid="receipt-item-1"]').should('contain', 'Product 1');
    cy.get('[data-testid="receipt-item-2"]').should('contain', 'Product 2');

    // Verify total amount is displayed
    cy.get('[data-testid="total-amount"]').should('be.visible');
    cy.get('[data-testid="total-amount"]').should('contain', '$150.00');

    // Verify order number is displayed
    cy.get('[data-testid="order-number"]').should('be.visible');
    cy.get('[data-testid="order-number"]').should('contain', 'ORD-123456');

    // Verify confirmation button is visible
    cy.get('[data-testid="confirm-order-button"]').should('be.visible');
  });

  it('should display error message when checkout fails', () => {
    // Intercept the failed checkout API call
    cy.intercept('POST', '/api/checkout/complete', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('checkoutFailed');

    // Add items to cart
    cy.get('[data-testid="add-to-cart-button"]').first().click();
    cy.get('[data-testid="product-1"]').first().click();
    cy.get('[data-testid="add-to-cart-button"]').first().click();
    cy.get('[data-testid="product-2"]').first().click();

    // Verify items are added
    cy.get('[data-testid="cart-item-count"]').should('contain', '2');

    // Proceed to checkout
    cy.get('[data-testid="checkout-button"]').click();

    // Verify checkout form is visible
    cy.get('[data-testid="checkout-form"]').should('be.visible');

    // Fill in shipping and billing details
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St');
    cy.get('[data-testid="shipping-city-input"]').type('Anytown');
    cy.get('[data-testid="shipping-state-input"]').type('CA');
    cy.get('[data-testid="shipping-zip-code-input"]').type('90210');

    cy.get('[data-testid="billing-address-input"]').type('123 Main St');

    // Verify payment details are filled
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Verify checkout button is enabled
    cy.get('[data-testid="checkout-button"]').should('be.enabled');

    // Click checkout button
    cy.get('[data-testid="checkout-button"]').click();

    // Wait for API call to complete
    cy.wait('@checkoutFailed');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Checkout failed');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify receipt is not displayed
    cy.get('[data-testid="receipt-section"]').should('not.exist');

    // Verify order number is not displayed
    cy.get('[data-testid="order-number"]').should('not.exist');

    // Verify confirmation button is not visible
    cy.get('[data-testid="confirm-order-button"]').should('not.exist');
  });
});
